INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(123843, 'ruRU', '', 'Урок завершён.', 24330),
(123844, 'ruRU', '', 'Чистый разум — упорядоченный разум.', 24330),
(123845, 'ruRU', '', 'Я никогда... не сдамся...', 24330),
(123846, 'ruRU', '', 'Вы все... такие же развращённые... как Хранитель...', 24330),
(123850, 'ruRU', '', '$n! Сюда!', 24330),
(123851, 'ruRU', '', 'С гибелью её лучшего чародея, вряд ли Элизанда пришлёт подкрепление. У нас есть пролом. Следуй за мной.', 24330),
(123852, 'ruRU', '', 'Я чувствую Ночной Колодец отсюда. Элизанда должна быть в настоящем отчаянии, чтобы перегружать Ночной Колодец подобным образом!', 24330),
(123862, 'ruRU', '', 'Ваше сопротивление бессмысленно!', 24330),
(123888, 'ruRU', '', 'Я готов обрушить барьер. Тебе нужно будет действовать быстро и обезопасить вход, прежде чем они поймут, что происходит.', 24330),
(123892, 'ruRU', '', 'Прочь, раб!', 24330),
(123893, 'ruRU', '', 'Твой народ хорошо нам служит, прислужник.', 24330),
(123894, 'ruRU', '', 'У меня нет времени на твои игры.', 24330),
(123895, 'ruRU', '', 'Где ты была, маленькое отребье?$B$BТы думала, мы не наблюдаем?', 24330),
(123897, 'ruRU', '', 'Жалкая попытка маскировки! Теперь ты заплатишь своей жизнью!', 24330),
(123906, 'ruRU', '', 'Многие Ночнорождённые были убиты, когда Элизанда и Легион напали. Нанеси ответный удар! Покажи этим дьяволам, что мы не потерпим тирании.', 24330),
(123907, 'ruRU', '', 'Элизанда и Легион заплатят за кровь, что они пролили. Им ещё многое предстоит ответить!', 24330),
(123908, 'ruRU', '', 'Это место небезопасно. Нам следует скоро уйти.', 24330),
(123909, 'ruRU', '', 'Вантир в опасности!', 24330),
(123919, 'ruRU', '', 'Патрули Легиона подходят всё ближе к Шал''Арану. Убей их, прежде чем они обнаружат наше местоположение!', 24330),
(123920, 'ruRU', '', 'Наше местоположение остаётся тайной... пока. Боюсь, это не последний раз, когда Шал''Арану угрожают.', 24330),
(123923, 'ruRU', '', 'Победа над Элизандой потребует силы, большей, чем наша собственная. Взойди к Лунному Горну и ищи благословение древних Лунного Дозора.', 24330),
(123924, 'ruRU', '', 'Элизанда опозорила наш народ, когда напала на Лунный Дозор. Поддерживая их традиции живыми, ты помогаешь нам искупить её проступок.', 24330),
(123930, 'ruRU', '', 'Ох. Хм. Значит, слухи правдивы? Прекрасного оружия Даларана больше нет? Мне нужно посетить похороны...\n\nПолагаю, Камень Души Ночнорождённых можно убедить работать с нами. Но сначала нам понадобится очень упорный генератор щита.', 24330),
(123931, 'ruRU', '', 'Силы Элизанды подстерегают беженцев, спасающихся из Сурамара через Алую Чащу. Отличная возможность испытать их боевые навыки!', 24330),
(123932, 'ruRU', '', 'Некогда гордые шал''дорай атакуют свой собственный народ? Ситуация даже более отчаянная, чем я представлял...', 24330),
(123933, 'ruRU', '', 'Шал''дорай бегут из Сурамара, пока силы Элизанды продвигаются через Алую Чащу. Иди, разгроми Ночнорождённых ради тех, кто пытается спастись из города.', 24330),
(123934, 'ruRU', '', 'Они убивают свой собственный народ за то, что те осмелились искать безопасность? Мы обрушим свой гнев на Элизанду за эту несправедливость!', 24330),
(123935, 'ruRU', '', 'Нам нужно распространить весть о прибытии Альянса. Расклей объявления по всему городу о том, что правление Великой Магистрикс скоро закончится. Вдохновляй шал''дорай на сопротивление!', 24330),
(123936, 'ruRU', '', 'Чем больше шал''дорай возьмутся за оружие, тем меньше моего народа погибнет при освобождении Сурамара.', 24330),
(123937, 'ruRU', '', 'Горожанам Сурамара нужно рассказать о прибытии Орды. Расклей объявления по всему городу. Пусть угнетённые знают, что помощь на подходе!', 24330),
(123938, 'ruRU', '', 'Шал''дорай нужно показать, что за этим хаосом есть будущее. Мы должны достичь как можно больше людей!', 24330),
(123939, 'ruRU', '', 'Наши припасы на исходе, но у врага их в избытке. Отправляйся в Сурамар и освободи припасы у сил Магистрикс!', 24330),
(123940, 'ruRU', '', 'Я наблюдал из своего трактира, как силы Элизанды нахлынули в Полумесяц.', 24330),
(123941, 'ruRU', '', 'Демонорождённые убивали всех, кто стоял у них на пути, но его не убили.', 24330),
(123942, 'ruRU', '', 'Он умолял их пощадить его народ.', 24330),
(123943, 'ruRU', '', 'Они сказали, что он станет примером для всех остальных.', 24330),
(123944, 'ruRU', '', 'Его телепортировали прочь. Куда, я не знаю.', 24330),
(123945, 'ruRU', '', 'Боевой дух возродился с прибытием свежих припасов. Ты отлично справился!', 24330),
(123946, 'ruRU', '', 'Истощающиеся припасы деморализуют наши войска. Отправляйся в Сурамар и захвати припасы у угнетателей-Ночнорождённых!', 24330),
(123947, 'ruRU', '', 'Эти припасы окажутся решающими для продолжения нашей кампании. Орда идёт вперёд!', 24330);
